mapper.update:
UPDATE dlp_scans
   SET status = 'PENDING',
       attempts = attempts + 1,
       updated_at = #{now}
 WHERE status = 'PROCESSING' AND updated_at < #{threshold}

UPDATE dlp_scans
   SET status = 'PENDING',
       last_error = #{error},
       updated_at = #{now}
 WHERE id = #{id}

UPDATE dlp_scans
   SET status = 'FAILED',
       last_error = #{error},
       updated_at = #{now}
 WHERE id = #{id}
